mapper.select:
        select  t.domain,t.name,t.mapping_key,t.mapping_key mappingKey,t.remark,t.status_cd,t.status_cd statusCd,t.id,t.value 
from c_mapping t 
where 1 =1 

   and t.domain= #{domain}


   and t.name= #{name}


   and t.mapping_key= #{mappingKey}


   and t.remark= #{remark}


   and t.status_cd= #{statusCd}


   and t.id= #{id}


   and t.value= #{value}

order by t.create_time desc

   limit #{page}, #{row}

mapper.update:
        update  c_mapping t set t.status_cd = #{statusCd}

,t.b_id = #{newBId}


, t.domain= #{domain}


, t.name= #{name}


, t.mapping_key= #{mappingKey}


, t.remark= #{remark}


, t.value= #{value}

 where 1=1 
and t.id= #{id}

mapper.select:
        select  count(1) count 
from c_mapping t 
where 1 =1 

   and t.domain= #{domain}


   and t.name= #{name}


   and t.mapping_key= #{mappingKey}


   and t.remark= #{remark}


   and t.status_cd= #{statusCd}


   and t.id= #{id}


   and t.value= #{value}
